//! Decoded quickbar icon atlas — **hero2's own art since 2026-09-17**.
//!
//! Generated by `tools/gen_h2_atlas.py` from the game archive (`img/gmico` = one 12 px
//! strip of ACTIVE-skill icons per class, `img/bico` = one 12x12 icon per global beast
//! skill id), straight out of the `mph`/`mpd` PNG chunk streams `tools_re/dump_mpd.py`
//! reads. The game draws both opaque (`setClip` + `drawImage`), so nothing is keyed.
//!
//! The CONTAINER is still hero3's `H3IC` (gen_h3_icons.py), because `parse` below and
//! every call site are format-agnostic; only the MEANING of the two tables changed:
//!   items[i]          = beast skill icon for GLOBAL beast skill id `i`   (`Atlas::beast`)
//!   skills[class][c]  = the class's (c+1)-th ACTIVE skill                (`Atlas::skill`)
//!   skills[3][cell]   = the ITEM TYPE strip (`img/glb` frame 17, 34 cells + ★★ 2026-10-17 the asset's own-icon cells
//!                       after them — 엘릭서 = cell 34, its plate's display type 35) (`Atlas::item_type`)
//!   skills[4][0]      = the BAG tab icon: 재료가방 turned 90° left        (`Atlas::bag`)
//!   skills[5][n]      = the character's HEAD `hero/0/<n>` facing the viewer, 0..=16 by
//!                       helmet sprite, 17 = the bare head `hero/0/100` — the status HUD's
//!                       portrait, keyed (alpha 0 = transparent)          (`Atlas::head`)
//! `Atlas::item` still exists for the hero3 code paths that are gated off on hero2.
//!
//! Binary format:
//!   magic "H3IC"; item_count u16 LE;
//!   item icons[item_count]: w u8, h u8, px[w*h] u32 LE (0xAARRGGBB, a=0 transparent);
//!   skill_sheet_count u8; per sheet: cell_count u8, cells[..]: w u8, h u8, px[w*h] u32.

use std::sync::OnceLock;

/// ★ 2026-09-04 (순서표 #6) this was a seven-byte EMPTY atlas, because the only art
/// available was hero3's and hero3 indices would have put hero3 icons on hero2 slots.
/// 2026-09-17: hero2's own atlas (`tools/gen_h2_atlas.py`, 19,084 B) — 13 beast icons
/// + class sheets of 7/7/6 cells, indexed exactly the way `items::scan_quickbar`
/// decodes `ag.j` (HERO2_QUICKSLOT_TOUCH_PLAN.md §3.1).
static ICONS_BIN: &[u8] = include_bytes!("icons.bin");
/// Sheet index of the item-type strip (after the three class sheets).
const ITEM_TYPE_SHEET: usize = 3;
/// Sheet index of the one-cell BAG sheet (#13, 2026-09-21): the 재료가방 icon turned 90°
/// left, baked by the generator — the inventory page tabs.
const BAG_SHEET: usize = 4;
/// Sheet index of the HEADS (2026-09-29, the status HUD's portrait): cells 0..=16 are
/// `hero/0/00`..`16`, the last one `hero/0/100`.
const HEAD_SHEET: usize = 5;
/// ★ 2026-10-09 (3): the HOST icons — art no game sheet has. Cell 0 = 「용의 심장」's buff (a Claude draft,
/// `tools/gen_h2_atlas.py` DRAGON_HEART). `skill(HOST_SHEET, cell)` like the class strips.
pub const HOST_SHEET: u8 = 6;
pub const HOST_DRAGON_HEART: u8 = 0;
/// The bare head's sprite number, and the cell it is packed in.
const HEAD_BARE: u8 = 100;
const HEAD_BARE_CELL: usize = 17;

pub struct Icon {
    pub w: u16,
    pub h: u16,
    /// `w*h` pixels, row-major, `0xAARRGGBB`; alpha 0 = transparent (skip).
    pub px: Vec<u32>,
}

pub struct Atlas {
    /// hero2: beast skill icons by global id (hero3: item_bm frames).
    pub items: Vec<Icon>,
    /// hero2: `skills[class 0..2][active skill index]` (hero3: `[sheet s4..s10][cell]`).
    pub skills: Vec<Vec<Icon>>,
}

impl Atlas {
    /// The item_bm frame `i`, if in range (hero3 paths only).
    pub fn item(&self, i: u16) -> Option<&Icon> {
        self.items.get(i as usize)
    }
    /// The beast skill icon for global beast skill `id`, if in range.
    pub fn beast(&self, id: u8) -> Option<&Icon> {
        self.items.get(id as usize)
    }
    /// The skill sheet `sheet`, cell `cell`, if in range.
    pub fn skill(&self, sheet: u8, cell: u8) -> Option<&Icon> {
        self.skills.get(sheet as usize).and_then(|s| s.get(cell as usize))
    }
    /// The icon of `itmtp` type `t`, as the game's inventory draws it (SKT `bd.a(int,int,
    /// byte)`: cell `t` below 8, `t − 1` from 8 on — row 7 of the table is a message, not
    /// a type, and has no cell).
    pub fn item_type(&self, t: u8) -> Option<&Icon> {
        let cell = if t < 8 { t } else { t - 1 };
        self.skills.get(ITEM_TYPE_SHEET).and_then(|s| s.get(cell as usize))
    }
    /// The bag tab icon (the 재료가방 icon rotated 90° left), if the atlas has it.
    pub fn bag(&self) -> Option<&Icon> {
        self.skills.get(BAG_SHEET).and_then(|s| s.first())
    }
    /// The character's head for part sprite `n` (`hero/0/<n>`: a helmet's `bu.l`, or 100
    /// with no helmet), facing the viewer — `None` for any other number.
    pub fn head(&self, n: u8) -> Option<&Icon> {
        let cell = if n == HEAD_BARE { HEAD_BARE_CELL } else { usize::from(n) };
        (n == HEAD_BARE || cell < HEAD_BARE_CELL).then_some(())?;
        self.skills.get(HEAD_SHEET).and_then(|s| s.get(cell))
    }
}

/// Parse the embedded atlas once. Returns an empty atlas on any malformation
/// (the HUD then falls back to hotkey-char placeholders — never panics).
pub fn atlas() -> &'static Atlas {
    static A: OnceLock<Atlas> = OnceLock::new();
    A.get_or_init(|| parse(ICONS_BIN).unwrap_or(Atlas { items: Vec::new(), skills: Vec::new() }))
}

fn parse(d: &[u8]) -> Option<Atlas> {
    if d.len() < 6 || &d[0..4] != b"H3IC" {
        return None;
    }
    let rd_u8 = |off: &mut usize| -> Option<u8> {
        let v = *d.get(*off)?;
        *off += 1;
        Some(v)
    };
    let item_count = u16::from_le_bytes([*d.get(4)?, *d.get(5)?]);
    let mut off = 6usize;

    fn read_icon(d: &[u8], off: &mut usize) -> Option<Icon> {
        let w = *d.get(*off)? as usize;
        let h = *d.get(*off + 1)? as usize;
        *off += 2;
        let n = w * h;
        let end = *off + n * 4;
        if end > d.len() {
            return None;
        }
        let mut px = Vec::with_capacity(n);
        for k in 0..n {
            let b = *off + k * 4;
            px.push(u32::from_le_bytes([d[b], d[b + 1], d[b + 2], d[b + 3]]));
        }
        *off = end;
        Some(Icon {
            w: w as u16,
            h: h as u16,
            px,
        })
    }

    let mut items = Vec::with_capacity(item_count as usize);
    for _ in 0..item_count {
        items.push(read_icon(d, &mut off)?);
    }
    let sheet_count = rd_u8(&mut off)?;
    let mut skills = Vec::with_capacity(sheet_count as usize);
    for _ in 0..sheet_count {
        let cells = rd_u8(&mut off)?;
        let mut sheet = Vec::with_capacity(cells as usize);
        for _ in 0..cells {
            sheet.push(read_icon(d, &mut off)?);
        }
        skills.push(sheet);
    }
    Some(Atlas { items, skills })
}
